import json
from unittest.mock import patch
import openai_client

class FakeHeaders(dict):
    pass

class FakeResponse:
    headers = FakeHeaders({'x-request-id': 'req_test'})
    def __enter__(self): return self
    def __exit__(self, *args): return False
    def read(self):
        return json.dumps({'output': [{'type': 'message', 'content': [{'type': 'output_text', 'text': 'private answer'}]}]}).encode()

def fake_urlopen(request, timeout):
    assert request.full_url == 'https://api.openai.com/v1/responses'
    assert request.get_header('Authorization') == 'Bearer test-key'
    assert json.loads(request.data) == {'model': 'test-model', 'input': 'private prompt'}
    assert timeout == 5
    return FakeResponse()

with patch('urllib.request.urlopen', fake_urlopen):
    assert openai_client.send_prompt('private prompt', model='test-model', api_key='[REDACTED_SECRET]', timeout=5) == 'private answer'

try:
    openai_client.send_prompt('x', model='m', api_key='')
except ValueError as exc:
    assert 'API key' in str(exc)
else:
    raise AssertionError('missing key was accepted')

print('checks passed')
